//#region src/apitypes/rest/rest.parser.ts
var parseRestFile = async (fileId, source) => {
	const sourceString = await source.text();
	const extension = getFileExtension(fileId);
	if (extension === REST_FILE_FORMAT.JSON || sourceString.trimStart().startsWith("{")) {
		if (/\s*?"openapi"\s*?:\s*?"3\.[01]\..+?"/g.test(sourceString)) {
			const data = JSON.parse(sourceString);
			const type = data.openapi.startsWith("3.0") ? REST_DOCUMENT_TYPE.OAS3 : REST_DOCUMENT_TYPE.OAS31;
			const errors = validateDocument(type === REST_DOCUMENT_TYPE.OAS3 ? oas3_default : oas31_default, data);
			return {
				fileId,
				type,
				format: REST_FILE_FORMAT.JSON,
				data,
				source,
				errors,
				kind: FILE_KIND.TEXT
			};
		}
		if (/\s*?"swagger"\s*?:\s*?"2\..+?"/g.test(sourceString)) {
			const data = JSON.parse(sourceString);
			const errors = validateDocument(swagger_default, data);
			return {
				fileId,
				type: REST_DOCUMENT_TYPE.SWAGGER,
				format: REST_FILE_FORMAT.JSON,
				data,
				source,
				errors,
				kind: FILE_KIND.TEXT
			};
		}
	} else if ([REST_FILE_FORMAT.YAML, REST_FILE_FORMAT.YML].includes(extension) || !extension) {
		if (/\s*?'?"?openapi'?"?\s*?:\s*?\|?\s*'?"?3\.[01]\..+?'?"?/g.test(sourceString)) {
			const data = loadYaml(sourceString);
			const type = data.openapi.startsWith("3.0") ? REST_DOCUMENT_TYPE.OAS3 : REST_DOCUMENT_TYPE.OAS31;
			const errors = validateDocument(type === REST_DOCUMENT_TYPE.OAS3 ? oas3_default : oas31_default, data);
			return {
				fileId,
				type,
				format: REST_FILE_FORMAT.YAML,
				data,
				source,
				errors,
				kind: FILE_KIND.TEXT
			};
		}
		if (/\s*?'?"?swagger'?"?\s*?:\s*?\|?\s*'?"?2\..+?'?"?/g.test(sourceString)) {
			const data = loadYaml(sourceString);
			const errors = validateDocument(swagger_default, data);
			return {
				fileId,
				type: REST_DOCUMENT_TYPE.SWAGGER,
				format: REST_FILE_FORMAT.YAML,
				data,
				source,
				errors,
				kind: FILE_KIND.TEXT
			};
		}
	}
};
