var buildUnknownDocument = async (parsedFile, file, ctx) => {
	const { fileId, slug = "", publish, ...metadata } = file;
	const { type, format, source } = parsedFile;
	const parsedData = parsedFile.data;
	let description = "";
	let dependencies = [];
	let bundledFileData = void 0;
	if (format === FILE_FORMAT.JSON || format === FILE_FORMAT.YAML) {
		description = isObject(parsedData) && isString(parsedData.description) ? parsedData.description : "";
		if (ctx.configuration?.bundleComponents) {
			const { data, dependencies: fileDependencies } = await getBundledFileDataWithDependencies(fileId, ctx.parsedFileResolver, createBundlingErrorHandler(ctx, fileId));
			bundledFileData = data;
			dependencies = fileDependencies;
		}
	}
	return {
		fileId,
		type,
		format,
		data: bundledFileData || parsedData || "",
		slug,
		publish,
		filename: fileId,
		title: getDocumentTitle(fileId),
		dependencies,
		description,
		operationIds: [],
		metadata,
		errors: parsedFile.errors?.length ?? 0,
		source,
		versionInternalDocument: createVersionInternalDocument(slug)
	};
};
var buildBinaryDocument = async (parsedFile, file) => {
	const { fileId, slug = "", publish, ...metadata } = file;
	const { type, format, source } = parsedFile;
	return {
		data: "",
		fileId,
		type,
		format,
		slug,
		title: getDocumentTitle(fileId),
		dependencies: [],
		description: "",
		operationIds: [],
		publish,
		filename: fileId,
		metadata,
		source,
		versionInternalDocument: createVersionInternalDocument(slug)
	};
};
var dumpUnknownDocument = (document) => {
	if (!document.source) throw new Error(`Document with fileId = ${document.fileId} does not have source`);
	return document.source;
};
